609→@@ -0,0 +1,112 @@
610→+import { useState, useCallback } from 'react';
611→+import { Modal } from '../ui/Modal';
612→+import { useUploadStore } from '../../stores/upload.store';
613→+import type { PendingReplacement } from '../../stores/upload.store';
614→+import { useFileOperations } from '../../hooks/useFileOperations';
615→+import { unpinFromIpfs } from '../../lib/api/ipfs';
616→+import { useQuotaStore } from '../../stores/quota.store';
617→+import '../../styles/dialogs.css';
618→+
619→+type ReplaceFileDialogProps = {
620→+  replacements: PendingReplacement[];
621→+  onComplete: () => void;
622→+};
623→+
624→+/**
625→+ * Dialog shown when uploaded files have names that already exist in the folder.
626→+ * Offers Replace (creates version) or Skip (discards the upload) for each file.
627→+ */
628→+export function ReplaceFileDialog({ replacements, onComplete }: ReplaceFileDialogProps) {
629→+  const { updateFile } = useFileOperations();
630→+  const [currentIndex, setCurrentIndex] = useState(0);
631→+  const [isLoading, setIsLoading] = useState(false);
632→+
633→+  const current = replacements[currentIndex];
634→+  const isLast = currentIndex >= replacements.length - 1;
635→+
636→+  const advance = useCallback(() => {
637→+    if (isLast) {
638→+      useUploadStore.getState().clearPendingReplacements();
639→+      onComplete();
640→+    } else {
641→+      setCurrentIndex((i) => i + 1);
642→+    }
643→+  }, [isLast, onComplete]);
644→+
645→+  const handleReplace = useCallback(async () => {
646→+    if (!current || isLoading) return;
647→+    setIsLoading(true);
648→+    try {
649→+      await updateFile(current.parentId, {
650→+        fileId: current.fileId,
651→+        newCid: current.encryptedData.cid,
652→+        newFileKeyEncrypted: current.encryptedData.wrappedKey,
653→+        newFileIv: current.encryptedData.iv,
654→+        newSize: current.encryptedData.size,
655→+        newEncryptionMode: current.encryptedData.encryptionMode,
656→+        forceVersion: true,
657→+      });
658→+      advance();
659→+    } catch (err) {
660→+      console.error('[replace] Failed to replace file:', err);
661→+      // Clean up orphaned pin + quota on failure
662→+      void unpinFromIpfs(current.encryptedData.cid).catch(() => {});
663→+      useQuotaStore.getState().removeUsage(current.encryptedData.size);
664→+      advance();
665→+    } finally {
666→+      setIsLoading(false);
667→+    }
668→+  }, [current, isLoading, updateFile, advance]);
669→+
670→+  const handleSkip = useCallback(() => {
671→+    if (!current || isLoading) return;
672→+    // Unpin the orphaned upload since user chose to skip
673→+    void unpinFromIpfs(current.encryptedData.cid).catch(() => {});
674→+    useQuotaStore.getState().removeUsage(current.encryptedData.size);
675→+    advance();
676→+  }, [current, isLoading, advance]);
677→+
678→+  const handleClose = useCallback(() => {
679→+    if (isLoading) return;
680→+    // Skip all remaining replacements and clean up orphaned pins + quota
681→+    for (let i = currentIndex; i < replacements.length; i++) {
682→+      void unpinFromIpfs(replacements[i].encryptedData.cid).catch(() => {});
683→+      useQuotaStore.getState().removeUsage(replacements[i].encryptedData.size);
684→+    }
685→+    useUploadStore.getState().clearPendingReplacements();
686→+    onComplete();
687→+  }, [isLoading, currentIndex, replacements, onComplete]);
688→+
689→+  if (!current) return null;
690→+
691→+  const remaining = replacements.length > 1 ? ` (${currentIndex + 1}/${replacements.length})` : '';
692→+
693→+  return (
694→+    <Modal open={true} onClose={handleClose} title={`Replace File${remaining}`}>
695→+      <div className="dialog-content">
696→+        <p className="dialog-message">
697→+          {`A file named "${current.fileName}" already exists in this folder. Replace it? The current version will be saved in version history.`}
698→+        </p>
699→+        <div className="dialog-actions">
700→+          <button
701→+            type="button"
702→+            className="dialog-button dialog-button--secondary"
703→+            onClick={handleSkip}
704→+            disabled={isLoading}
705→+          >
706→+            Skip
707→+          </button>
708→+          <button
709→+            type="button"
710→+            className="dialog-button dialog-button--primary"
711→+            onClick={handleReplace}
712→+            disabled={isLoading}
713→+            data-testid="replace-file-confirm"
714→+          >
715→+            {isLoading ? 'Replacing...' : 'Replace'}
716→+          </button>
717→+        </div>
718→+      </div>
719→+    </Modal>
720→+  );
721→+}
