240→+#[test]
241→+fn bin_entry_content_cid_roundtrip() {
242→+    let private_key = hex::decode(ECIES_TEST_PRIVATE_KEY).unwrap();
243→+    let public_key = hex::decode(ECIES_TEST_PUBLIC_KEY).unwrap();
244→+
245→+    let metadata = bin::RecycleBinMetadata {
246→+        version: "v1".to_string(),
247→+        sequence_number: 1,
248→+        entries: vec![bin::BinEntry {
249→+            id: "file-cid-test".to_string(),
250→+            item_type: bin::BinItemType::File,
251→+            name: "photo.jpg".to_string(),
252→+            original_parent_ipns_name: "k51qzi5uqu5dlvj2bv6qmx8snx6m8xq7nprfqqopzz6p0".to_string(),
253→+            original_path: "My Vault / Photos".to_string(),
254→+            deleted_at: 1700000000000,
255→+            size: 12345,
256→+            mime_type: "image/jpeg".to_string(),
257→+            content_cid: Some("REDACTED".to_string()),
258→+            content_size: Some(12345),
259→+            version_cids: None,
260→+            file_pointer: Some(FilePointer {
261→+                id: "fp-cid-test".to_string(),
262→+                name: "photo.jpg".to_string(),
263→+                file_meta_ipns_name: "k51filecidtest".to_string(),
264→+                ipns_private_key_encrypted: Some("deadbeef".to_string()),
265→+                created_at: 1700000000000,
266→+                modified_at: 1700000000000,
267→+            }),
268→+            folder_entry: None,
269→+        }],
270→+    };
271→+
272→+    let encrypted = bin::encrypt_bin_metadata(&metadata, &public_key).unwrap();
273→+    let decrypted = bin::decrypt_bin_metadata(&encrypted, &private_key).unwrap();
274→+
275→+    assert_eq!(decrypted.entries.len(), 1);
276→+    let entry = &decrypted.entries[0];
277→+    assert_eq!(
278→+        entry.content_cid.as_deref(),
279→+        Some("REDACTED"),
280→+        "content_cid should survive encrypt/decrypt roundtrip"
281→+    );
282→+    assert_eq!(
283→+        entry.content_size,
284→+        Some(12345),
285→+        "content_size should survive encrypt/decrypt roundtrip"
286→+    );
287→+}
