 31→  const handleFileDrop = useCallback(
 32→    async (files: File[], folderId: string): Promise<boolean> => {
 33→      // Filter out oversized files
 34→      const oversized = files.filter((f) => f.size > MAX_FILE_SIZE);
 35→      if (oversized.length > 0) {
 36→        useUploadStore
 37→          .getState()
 38→          .setError(`Files exceed 100MB limit: ${oversized.map((f) => f.name).join(', ')}`);
 39→        return false;
 40→      }
 41→
 42→      if (files.length === 0) return false;
 43→
 44→      // Check quota
 45→      const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 46→      if (!canUpload(totalSize)) {
 47→        useUploadStore.getState().setError('Not enough storage space for these files');
 48→        return false;
 49→      }
 50→
 51→      // Check for duplicates within batch (independent of folder cache)
 52→      const batchNames = new Set<string>();
 53→      for (const f of files) {
 54→        if (batchNames.has(f.name)) {
 55→          useUploadStore.getState().setError(`Duplicate file name in selection: ${f.name}`);
 56→          return false;
 57→        }
 58→        batchNames.add(f.name);
 59→      }
 60→
 61→      // Identify which files already exist in the target folder
 62→      const folder = useFolderStore.getState().folders[folderId];
 63→      const existingByName = new Map<string, string>(); // name → fileId
 64→      const existingFolderNames = new Set<string>();
 65→      if (folder) {
 66→        for (const child of folder.children) {
 67→          if (child.type === 'file') {
 68→            existingByName.set(child.name, child.id);
 69→          } else if (child.type === 'folder') {
 70→            existingFolderNames.add(child.name);
 71→          }
 72→        }
 73→      }
 74→
 75→      // Fail fast on file–folder name collisions (no Replace/Skip for folders)
 76→      const folderNameConflicts = files.filter((f) => existingFolderNames.has(f.name));
 77→      if (folderNameConflicts.length > 0) {
 78→        useUploadStore
 79→          .getState()
 80→          .setError(
 81→            `Cannot upload file(s) with the same name as an existing folder: ${folderNameConflicts.map((f) => f.name).join(', ')}`
 82→          );
 83→        return false;
 84→      }
