558→export async function permanentlyDeleteBatch(params: {
559→  entryIds: string[];
560→  userPublicKey: Uint8Array;
561→  userPrivateKey: Uint8Array;
562→}): Promise<void> {
563→  const { entryIds, userPublicKey, userPrivateKey } = params;
564→  if (entryIds.length === 0) return;
565→
566→  const binStore = useBinStore.getState();
567→  const idsSet = new Set(entryIds);
