569→
570→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
571→  for (const entry of entriesToDelete) {
572→    try {
573→      await cleanupEntryCids(entry, userPrivateKey);
574→    } catch (err) {
575→      console.error(`[Bin] CID cleanup failed for entry ${entry.id}:`, err);
576→    }
577→  }
578→
579→  // Remove all from bin metadata in a single publish
580→  await removeEntriesFromBin(entryIds, { userPublicKey, userPrivateKey });
581→}
