806→async function cleanupFolderCids(
807→  folderEntry: FolderEntry,
808→  userPrivateKey: Uint8Array
809→): Promise<void> {
810→  let folderMetadataCid: string | null = null;
811→  try {
812→    // Step 1: Unwrap the folder's AES key using user's private key (ECIES)
813→    const wrappedFolderKey = hexToBytes(folderEntry.folderKeyEncrypted);
814→    const folderKey = await unwrapKey(wrappedFolderKey, userPrivateKey);
815→
816→    // Step 2: Resolve folder's IPNS to get its metadata CID
817→    const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
818→    if (!resolved?.cid) return;
819→    folderMetadataCid = resolved.cid;
820→
821→    // Step 3: Fetch and decrypt the folder metadata
822→    const metaBytes = await fetchFromIpfs(resolved.cid);
823→    const metaJson = new TextDecoder().decode(metaBytes);
824→    const encrypted = JSON.parse(metaJson) as EncryptedFolderMetadata;
825→    const folderMeta = await decryptFolderMetadata(encrypted, folderKey);
826→
827→    // Step 4: For each child, unpin CIDs
828→    for (const child of folderMeta.children) {
829→      try {
830→        if (child.type === 'file') {
831→          const fp = child as FilePointer;
832→          // Decrypt file metadata to get content CID
833→          const fileResolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
834→          if (fileResolved?.cid) {
835→            const fileMetaBytes = await fetchFromIpfs(fileResolved.cid);
836→            const fileMetaJson = new TextDecoder().decode(fileMetaBytes);
837→            const encryptedFileMeta = JSON.parse(fileMetaJson) as EncryptedFileMetadata;
838→            const fileMeta = await decryptFileMetadata(encryptedFileMeta, folderKey);
839→            if (fileMeta.cid) {
840→              await unpinFromIpfs(fileMeta.cid);
841→              if (Number.isFinite(fileMeta.size)) {
842→                useQuotaStore.getState().removeUsage(fileMeta.size);
843→              }
844→            }
845→            // Unpin any historical version CIDs
846→            await unpinVersionCids(fileMeta);
847→            // Also unpin the file metadata CID
848→            await unpinFromIpfs(fileResolved.cid).catch(() => {});
849→          }
850→        } else if (child.type === 'folder') {
851→          // Subfolder: folderKeyEncrypted is ECIES-wrapped with the user's publicKey
852→          const subFe = child as FolderEntry;
853→          await cleanupFolderCids(subFe, userPrivateKey);
854→        }
855→      } catch (childErr) {
856→        console.error(`[Bin] Failed to cleanup CIDs for child ${child.name}:`, childErr);
857→      }
