 53→      void unpinFromIpfs(current.encryptedData.cid).catch(() => {});
 54→      useQuotaStore.getState().removeUsage(current.encryptedData.size);
 55→      advance();
 56→    } finally {
 57→      setIsLoading(false);
 58→    }
 59→  }, [current, isLoading, updateFile, advance]);
 60→
 61→  const handleSkip = useCallback(() => {
 62→    if (!current || isLoading) return;
 63→    // Unpin the orphaned upload since user chose to skip
 64→    void unpinFromIpfs(current.encryptedData.cid).catch(() => {});
 65→    useQuotaStore.getState().removeUsage(current.encryptedData.size);
 66→    advance();
 67→  }, [current, isLoading, advance]);
 68→
 69→  const handleClose = useCallback(() => {
 70→    if (isLoading) return;
 71→    // Skip all remaining replacements and clean up orphaned pins + quota
 72→    for (let i = currentIndex; i < replacements.length; i++) {
 73→      void unpinFromIpfs(replacements[i].encryptedData.cid).catch(() => {});
 74→      useQuotaStore.getState().removeUsage(replacements[i].encryptedData.size);
 75→    }
