 83→
 84→  return (
 85→    <Modal open={true} onClose={handleClose} title={`Replace File${remaining}`}>
 86→      <div className="dialog-content">
 87→        <p className="dialog-message">
 88→          {`A file named "${current.fileName}" already exists in this folder. Replace it? The current version will be saved in version history.`}
 89→        </p>
 90→        <div className="dialog-actions">
 91→          <button
 92→            type="button"
 93→            className="dialog-button dialog-button--secondary"
 94→            onClick={handleSkip}
 95→            disabled={isLoading}
 96→          >
 97→            Skip
 98→          </button>
 99→          <button
100→            type="button"
101→            className="dialog-button dialog-button--primary"
102→            onClick={handleReplace}
103→            disabled={isLoading}
104→            data-testid="replace-file-confirm"
105→          >
106→            {isLoading ? 'Replacing...' : 'Replace'}
107→          </button>
108→        </div>
109→      </div>
110→    </Modal>
111→  );
112→}
