668→/**
669→ * Remove entries from bin metadata and publish the updated metadata.
670→ */
671→async function removeEntriesFromBin(
672→  entryIds: string[],
673→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
674→): Promise<void> {
675→  const binStore = useBinStore.getState();
676→  const idsToRemove = new Set(entryIds);
677→  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
678→  const newSeq = binStore.sequenceNumber + 1;
679→
680→  const metadata: RecycleBinMetadata = {
681→    version: BIN_METADATA_VERSION,
682→    sequenceNumber: newSeq,
683→    entries: remainingEntries,
684→  };
