695→
696→/**
697→ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
698→ *
699→ * Files: use stored contentCid if available, else fall back to IPNS resolution.
700→ * Folders: unwrap folderKey, decrypt folder metadata, decrypt each nested file's
701→ * metadata to get CID for unpinning. Recurses for subfolders.
702→ */
703→async function cleanupEntryCids(entry: BinEntry, userPrivateKey: Uint8Array): Promise<void> {
704→  if (entry.itemType === 'file') {
705→    await unpinFileCids(entry);
706→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
707→    await cleanupFolderCids(entry.folderEntry, userPrivateKey);
708→  }
709→}
710→
711→/**
712→ * Unpin a single file's content and metadata CIDs, and update quota.
713→ *
714→ * Prefers stored contentCid (captured at soft-delete time) to avoid
715→ * re-decrypting encrypted file metadata (which was the GAP-1 bug).
716→ * Falls back to legacy IPNS resolution for old entries without contentCid.
717→ */
718→async function unpinFileCids(entry: BinEntry): Promise<void> {
719→  try {
720→    // Preferred path: use stored contentCid from soft-delete time
721→    if (entry.contentCid) {
722→      await unpinFromIpfs(entry.contentCid);
723→      if (Number.isFinite(entry.contentSize)) {
724→        useQuotaStore.getState().removeUsage(entry.contentSize!);
725→      }
726→      // Unpin version CIDs captured at soft-delete time
727→      if (entry.versionCids?.length) {
728→        for (const v of entry.versionCids) {
729→          await unpinFromIpfs(v.cid).catch(() => {});
730→          if (Number.isFinite(v.size)) {
731→            useQuotaStore.getState().removeUsage(v.size);
732→          }
733→        }
734→      }
735→      // Also unpin the file metadata IPNS record CID
736→      if (entry.filePointer) {
737→        const resolved = await resolveIpnsRecord(entry.filePointer.fileMetaIpnsName);
738→        if (resolved?.cid) {
739→          await unpinFromIpfs(resolved.cid).catch(() => {});
740→        }
741→      }
742→      return;
743→    }
744→
745→    // Fallback for legacy entries without contentCid:
746→    // Resolve IPNS and attempt to interpret file metadata as plaintext JSON.
747→    // NOTE: For encrypted file metadata ({ iv, data }), JSON.parse will usually
748→    // succeed, but the parsed object will not have cid/size, so no content unpin
749→    // or quota reclaim happens (the original GAP-1 bug). Entries that hit this
750→    // path may log an error but will not crash the delete flow.
751→    if (!entry.filePointer) return;
752→    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
753→    if (!fileIpnsName) return;
754→
755→    const resolved = await resolveIpnsRecord(fileIpnsName);
756→    if (!resolved?.cid) return;
757→
758→    const metaBytes = await fetchFromIpfs(resolved.cid);
759→    const metaJson = new TextDecoder().decode(metaBytes);
760→    const fileMeta = JSON.parse(metaJson);
761→
762→    if (fileMeta.cid) {
763→      await unpinFromIpfs(fileMeta.cid);
764→      if (Number.isFinite(fileMeta.size)) {
765→        useQuotaStore.getState().removeUsage(fileMeta.size);
766→      }
767→    }
768→    await unpinVersionCids(fileMeta);
769→
770→    await unpinFromIpfs(resolved.cid).catch(() => {});
771→  } catch (err) {
772→    console.error(`[Bin] CID cleanup failed for file ${entry.id}:`, err);
773→  }
774→}
775→
776→/**
777→ * Unpin version CIDs from a decrypted/parsed file metadata object and reclaim quota.
778→ * Best-effort: errors on individual versions are caught and logged.
779→ */
780→async function unpinVersionCids(fileMeta: {
781→  versions?: Array<{ cid?: string; size?: number }>;
782→}): Promise<void> {
783→  if (!Array.isArray(fileMeta.versions)) return;
784→  for (const version of fileMeta.versions) {
785→    try {
786→      if (version.cid) {
787→        await unpinFromIpfs(version.cid);
788→      }
789→      if (Number.isFinite(version.size)) {
790→        useQuotaStore.getState().removeUsage(version.size!);
791→      }
792→    } catch {
793→      // Best-effort for individual version cleanup
794→    }
795→  }
796→}
797→
798→/**
799→ * Recursively unpin all CIDs in a folder tree.
800→ *
801→ * Unwraps the folder's AES key using the user's private key, then decrypts
802→ * the folder metadata to enumerate children. For each file child, decrypts
803→ * the file metadata to extract the content CID for unpinning.
804→ * For subfolder children, recurses with the user's private key.
805→ */
806→async function cleanupFolderCids(
807→  folderEntry: FolderEntry,
808→  userPrivateKey: Uint8Array
809→): Promise<void> {
810→  let folderMetadataCid: string | null = null;
811→  try {
812→    // Step 1: Unwrap the folder's AES key using user's private key (ECIES)
813→    const wrappedFolderKey = hexToBytes(folderEntry.folderKeyEncrypted);
814→    const folderKey = await unwrapKey(wrappedFolderKey, userPrivateKey);
815→
816→    // Step 2: Resolve folder's IPNS to get its metadata CID
817→    const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
818→    if (!resolved?.cid) return;
819→    folderMetadataCid = resolved.cid;
820→
821→    // Step 3: Fetch and decrypt the folder metadata
822→    const metaBytes = await fetchFromIpfs(resolved.cid);
823→    const metaJson = new TextDecoder().decode(metaBytes);
824→    const encrypted = JSON.parse(metaJson) as EncryptedFolderMetadata;
825→    const folderMeta = await decryptFolderMetadata(encrypted, folderKey);
826→
827→    // Step 4: For each child, unpin CIDs
828→    for (const child of folderMeta.children) {
829→      try {
830→        if (child.type === 'file') {
831→          const fp = child as FilePointer;
832→          // Decrypt file metadata to get content CID
833→          const fileResolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
834→          if (fileResolved?.cid) {
835→            const fileMetaBytes = await fetchFromIpfs(fileResolved.cid);
836→            const fileMetaJson = new TextDecoder().decode(fileMetaBytes);
837→            const encryptedFileMeta = JSON.parse(fileMetaJson) as EncryptedFileMetadata;
838→            const fileMeta = await decryptFileMetadata(encryptedFileMeta, folderKey);
839→            if (fileMeta.cid) {
840→              await unpinFromIpfs(fileMeta.cid);
841→              if (Number.isFinite(fileMeta.size)) {
842→                useQuotaStore.getState().removeUsage(fileMeta.size);
843→              }
844→            }
845→            // Unpin any historical version CIDs
846→            await unpinVersionCids(fileMeta);
847→            // Also unpin the file metadata CID
848→            await unpinFromIpfs(fileResolved.cid).catch(() => {});
849→          }
850→        } else if (child.type === 'folder') {
851→          // Subfolder: folderKeyEncrypted is ECIES-wrapped with the user's publicKey
852→          const subFe = child as FolderEntry;
853→          await cleanupFolderCids(subFe, userPrivateKey);
854→        }
855→      } catch (childErr) {
856→        console.error(`[Bin] Failed to cleanup CIDs for child ${child.name}:`, childErr);
857→      }
858→    }
859→  } catch (err) {
860→    console.error(`[Bin] Folder CID cleanup failed for ${folderEntry.ipnsName}:`, err);
861→  } finally {
862→    // Always unpin the folder metadata CID, even if child cleanup threw
863→    if (folderMetadataCid) {
864→      await unpinFromIpfs(folderMetadataCid).catch(() => {});
865→    }
866→  }
867→}
868→
869→/**
870→ * Resolve the target folder for a restore operation.
871→ *
872→ * Walks the folder store to find a folder with the given IPNS name.
873→ * If not found, checks if the parent is in the bin (recursive restore).
874→ * Falls back to root folder.
875→ */
876→async function resolveTargetFolder(
877→  parentIpnsName: string,
878→  depth: number,
879→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
880→): Promise<FolderNode> {
881→  // Max recursion depth to prevent infinite loops
882→  if (depth > 5) {
883→    console.warn('[Bin] Max restore depth reached, falling back to root');
884→    return getRootFolder();
885→  }
886→
887→  // Look up folder by IPNS name in folder store
888→  const folders = useFolderStore.getState().folders;
889→  const targetFolder = Object.values(folders).find((f) => f.ipnsName === parentIpnsName);
890→
891→  if (targetFolder) {
892→    return targetFolder;
893→  }
894→
895→  // Check if parent is in the bin
896→  const binStore = useBinStore.getState();
897→  const parentBinEntry = binStore.entries.find(
898→    (e) => e.itemType === 'folder' && e.folderEntry && e.folderEntry.ipnsName === parentIpnsName
899→  );
900→
901→  if (parentBinEntry) {
902→    // Restore parent first (recursive, depth incremented)
903→    console.log(`[Bin] Restoring parent folder (id: ${parentBinEntry.id}) first`);
904→    await restoreFromBinInternal(
905→      {
906→        entryId: parentBinEntry.id,
907→        userPublicKey: params.userPublicKey,
908→        userPrivateKey: params.userPrivateKey,
909→      },
910→      depth + 1
911→    );
912→
913→    // After restoring parent, try to find it again
914→    const updatedFolders = useFolderStore.getState().folders;
915→    const restoredParent = Object.values(updatedFolders).find((f) => f.ipnsName === parentIpnsName);
916→    if (restoredParent) {
917→      return restoredParent;
918→    }
919→  }
920→
921→  // Parent truly gone -- restore to root
922→  console.warn(`[Bin] Original parent not found (${parentIpnsName}), restoring to root`);
923→  return getRootFolder();
924→}
925→
926→/**
927→ * Get the root folder from the folder store.
928→ */
929→function getRootFolder(): FolderNode {
930→  const folders = useFolderStore.getState().folders;
931→  const root = folders['root'];
932→  if (root) return root;
933→
934→  // Fallback: construct from vault store
935→  const vault = useVaultStore.getState();
936→  if (!vault.rootFolderKey || !vault.rootIpnsKeypair || !vault.rootIpnsName) {
937→    throw new Error('Vault not initialized - cannot restore to root');
938→  }
939→
940→  return {
941→    id: 'root',
942→    name: 'My Vault',
943→    ipnsName: vault.rootIpnsName,
944→    parentId: null,
945→    children: folders['root']?.children ?? [],
946→    isLoaded: true,
947→    isLoading: false,
948→    sequenceNumber: 0n,
949→    folderKey: vault.rootFolderKey,
950→    ipnsPrivateKey: vault.rootIpnsKeypair.privateKey,
951→  };
952→}
953→
954→/**
955→ * Get the FolderChild to restore from a bin entry.
956→ */
957→function getRestoredChild(entry: BinEntry): FolderChild {
958→  if (entry.itemType === 'file' && entry.filePointer) {
959→    return { ...entry.filePointer, modifiedAt: Date.now() };
960→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
961→    return { ...entry.folderEntry, modifiedAt: Date.now() };
962→  }
963→  throw new Error(`Bin entry ${entry.id} has no stored item reference`);
964→}
965→
966→/**
967→ * Check for name collisions and rename if needed.
968→ */
969→function resolveNameCollision(child: FolderChild, existingChildren: FolderChild[]): FolderChild {
970→  const existingNames = new Set(existingChildren.map((c) => c.name));
971→  if (!existingNames.has(child.name)) {
972→    return child;
973→  }
974→
975→  // Append " (restored)" suffix, incrementing if needed
976→  let newName = `${child.name} (restored)`;
977→  let counter = 2;
978→  while (existingNames.has(newName)) {
979→    newName = `${child.name} (restored ${counter})`;
980→    counter++;
981→  }
982→
983→  return { ...child, name: newName };
984→}
985→

