 800→    /// Rename or move a file/folder.
 801→    pub fn handle_rename(
 802→        fs: &mut CipherBoxFS,
 803→        parent: u64,
 804→        name: &OsStr,
 805→        newparent: u64,
 806→        newname: &OsStr,
 807→        reply: ReplyEmpty,
 808→    ) {
 809→        log::debug!(
 810→            "rename: {:?} (parent {}) -> {:?} (parent {})",
 811→            name, parent, newname, newparent,
 812→        );
 813→        let name_str = match name.to_str() {
 814→            Some(n) => n,
 815→            None => {
 816→                reply.error(libc::EINVAL);
 817→                return;
 818→            }
 819→        };
 820→        let newname_str = match newname.to_str() {
 821→            Some(n) => n,
 822→            None => {
 823→                reply.error(libc::EINVAL);
 824→                return;
 825→            }
 826→        };
 827→
 828→        // Find source inode (with FUSE-T truncated name fallback)
 829→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
 830→            Some(ino) => (ino, name_str.to_string()),
 831→            None => {
 832→                let parent_inode = match fs.inodes.get(parent) {
 833→                    Some(i) => i,
 834→                    None => {
 835→                        reply.error(libc::ENOENT);
 836→                        return;
 837→                    }
 838→                };
 839→                let children = parent_inode.children.clone().unwrap_or_default();
 840→                let mut matches: Vec<(u64, String)> = Vec::new();
 841→                for &child_ino in &children {
 842→                    if let Some(child) = fs.inodes.get(child_ino) {
 843→                        if is_platform_special(&child.name) {
 844→                            continue;
 845→                        }
 846→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
 847→                            matches.push((child_ino, child.name.clone()));
 848→                        }
 849→                    }
 850→                }
 851→                if matches.len() == 1 {
 852→                    log::debug!(
 853→                        "rename suffix-match: truncated {:?} matched full name {:?}",
 854→                        name_str, matches[0].1
 855→                    );
 856→                    (matches[0].0, matches[0].1.clone())
 857→                } else {
 858→                    log::debug!(
 859→                        "rename failed: {:?} not found (suffix matches: {})",
 860→                        name_str, matches.len()
 861→                    );
 862→                    reply.error(libc::ENOENT);
 863→                    return;
 864→                }
 865→            }
 866→        };
 867→
 868→        let name_str = &actual_name;
 869→
 870→        log::debug!(
 871→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
 872→            name_str, source_ino, parent, newname_str, newparent,
 873→        );
 874→
 875→        // If destination exists, handle replacement
 876→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
 877→            // Self-replace (rename "a" to "a" in same dir): no-op
 878→            if dest_ino == source_ino {
 879→                reply.ok();
 880→                return;
 881→            }
 882→
 883→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
 884→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
 885→                let source_is_dir = fs.inodes.get(source_ino)
 886→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
 887→                    .unwrap_or(false);
 888→                let dest_is_dir = matches!(
 889→                    dest_inode.kind,
 890→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
 891→                );
 892→                if source_is_dir && !dest_is_dir {
 893→                    reply.error(libc::ENOTDIR);
 894→                    return;
 895→                }
 896→                if !source_is_dir && dest_is_dir {
 897→                    reply.error(libc::EISDIR);
 898→                    return;
 899→                }
 900→
 901→                match &dest_inode.kind {
 902→                    InodeKind::Folder { .. } => {
 903→                        if let Some(ref children) = dest_inode.children {
 904→                            if !children.is_empty() {
 905→                                reply.error(libc::ENOTEMPTY);
 906→                                return;
 907→                            }
 908→                        }
 909→                    }
 910→                    InodeKind::File { cid, .. } => {
 911→                        if !cid.is_empty() {
 912→                            let cid_clone = cid.clone();
 913→                            let api = fs.api.clone();
 914→                            fs.rt.spawn(async move {
 915→                                let _ = crate::api::ipfs::unpin_content(
 916→                                    &api, &cid_clone,
 917→                                ).await;
 918→                            });
 919→                        }
 920→                    }
 921→                    _ => {}
 922→                }
 923→            }
 924→            fs.inodes.remove(dest_ino);
 925→        }
 926→
 927→        // Remove source from old parent's name index (NFC-normalized)
 928→        {
 929→            use unicode_normalization::UnicodeNormalization;
 930→            let nfc_key: String = name_str.nfc().collect();
 931→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
 932→        }
 933→
 934→        // Update the source inode's name and parent
 935→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
 936→            inode.name = newname_str.to_string();
 937→            inode.parent_ino = newparent;
 938→            inode.attr.ctime = SystemTime::now();
 939→        }
 940→
 941→        // Update the name lookup index for the new location (NFC-normalized)
 942→        {
 943→            use unicode_normalization::UnicodeNormalization;
 944→            let nfc_key: String = newname_str.nfc().collect();
 945→            fs.inodes.name_to_ino.insert(
 946→                (newparent, nfc_key),
 947→                source_ino,
 948→            );
 949→        }
 950→
 951→        if parent != newparent {
 952→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
 953→                if let Some(ref mut children) = old_parent.children {
 954→                    children.retain(|&c| c != source_ino);
 955→                }
 956→                old_parent.attr.mtime = SystemTime::now();
 957→                old_parent.attr.ctime = SystemTime::now();
 958→            }
 959→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
 960→                if let Some(ref mut children) = new_parent.children {
 961→                    children.push(source_ino);
 962→                }
 963→                new_parent.attr.mtime = SystemTime::now();
 964→                new_parent.attr.ctime = SystemTime::now();
 965→            }
 966→
 967→            if let Err(e) = fs.update_folder_metadata(parent) {
 968→                log::error!("Failed to update old parent metadata after rename: {}", e);
 969→            }
 970→            if let Err(e) = fs.update_folder_metadata(newparent) {
 971→                log::error!("Failed to update new parent metadata after rename: {}", e);
 972→            }
 973→        } else {
 974→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
 975→                parent_inode.attr.mtime = SystemTime::now();
 976→                parent_inode.attr.ctime = SystemTime::now();
 977→            }
 978→            if let Err(e) = fs.update_folder_metadata(parent) {
 979→                log::error!("Failed to update parent metadata after rename: {}", e);
 980→            }
 981→        }
 982→
 983→        reply.ok();
 984→    }
 985→
 986→    /// Build a human-readable breadcrumb path for a folder inode.
 987→    /// Walks parent_ino upward to root, concatenating names with " / ".
 988→    /// Example: "My Vault / Documents / Reports"
 989→    fn build_folder_path(fs: &CipherBoxFS, folder_ino: u64) -> String {
 990→        let mut parts = Vec::new();
 991→        let mut current = folder_ino;
 992→        for _ in 0..20 { // Safety limit to prevent infinite loops
 993→            match fs.inodes.get(current) {
 994→                Some(inode) => {
 995→                    match &inode.kind {
 996→                        InodeKind::Root { .. } => {
 997→                            parts.push("My Vault".to_string());
 998→                            break;
 999→                        }
1000→                        _ => {
1001→                            parts.push(inode.name.clone());
1002→                            current = inode.parent_ino;
1003→                        }
1004→                    }
1005→                }
1006→                None => break,
1007→            }
1008→        }
1009→        parts.reverse();
1010→        parts.join(" / ")
1011→    }
1012→}
